import { useApp } from "../context/AppContext";

export const Header = ({ baslik, sag }) => {
  const { oturum } = useApp();
  return (
    <div className="header">
      <div>
        <div className="logo">NAKLI<span className="logo-accent">YOL</span></div>
        {baslik && <div style={{ fontSize: 11, color: "var(--text3)", letterSpacing: 1, textTransform: "uppercase", marginTop: 1 }}>{baslik}</div>}
      </div>
      <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
        {sag}
        {oturum && (
          <div style={{ width: 32, height: 32, borderRadius: "50%", background: "var(--bg3)", border: "1px solid var(--border2)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 14 }}>
            {oturum.rol === "kamyoncu" ? "🚛" : oturum.rol === "admin" ? "⚙️" : "🏢"}
          </div>
        )}
      </div>
    </div>
  );
};

export const BottomNav = ({ aktif, setAktif, rol }) => {
  const kamyoncuMenu = [
    { key: "ilanlar",   icon: "📢", label: "İlanlar" },
    { key: "seferler",  icon: "🗺️", label: "Seferlerim" },
    { key: "mesajlar",  icon: "💬", label: "Mesajlar" },
    { key: "profil",    icon: "👤", label: "Profil" },
  ];
  const issizMenu = [
    { key: "ilanver",   icon: "➕", label: "İlan Ver" },
    { key: "teklifler", icon: "📋", label: "Teklifler" },
    { key: "mesajlar",  icon: "💬", label: "Mesajlar" },
    { key: "profil",    icon: "👤", label: "Profil" },
  ];
  const menu = rol === "kamyoncu" ? kamyoncuMenu : issizMenu;
  return (
    <div className="bottom-nav">
      {menu.map(m => (
        <button key={m.key} className={`nav-btn ${aktif === m.key ? "active" : ""}`} onClick={() => setAktif(m.key)}>
          <span className="nav-icon">{m.icon}</span>
          <span className="nav-label">{m.label}</span>
        </button>
      ))}
    </div>
  );
};

export const Sheet = ({ onClose, children }) => (
  <div className="sheet-overlay" onClick={onClose}>
    <div className="sheet" onClick={e => e.stopPropagation()}>
      <div className="sheet-handle" />
      {children}
    </div>
  </div>
);

export const Pill = ({ durum }) => {
  const map = {
    aktif:      { cls: "pill-green",  label: "Aktif" },
    onaylandı:  { cls: "pill-green",  label: "✓ Onaylandı" },
    bekliyor:   { cls: "pill-amber",  label: "⏳ Bekliyor" },
    reddedildi: { cls: "pill-red",    label: "✕ Reddedildi" },
    tam:        { cls: "pill-green",  label: "✓ Tam" },
    eksik:      { cls: "pill-amber",  label: "⚠ Eksik" },
    inceleniyor:{ cls: "pill-blue",   label: "🔍 İnceleniyor" },
    eşleşti:    { cls: "pill-orange", label: "🤝 Eşleşti" },
  };
  const { cls, label } = map[durum] || { cls: "pill-gray", label: durum };
  return <span className={`pill ${cls}`}>{label}</span>;
};

export const BelgeRow = ({ belge }) => (
  <div className="belge-row">
    <span className="belge-icon">📄</span>
    <span className="belge-name">{belge.ad}</span>
    <Pill durum={belge.ok ? "onaylandı" : "bekliyor"} />
  </div>
);

export const EmptyState = ({ icon, text }) => (
  <div className="empty">
    <div className="empty-icon">{icon}</div>
    <div className="empty-text">{text}</div>
  </div>
);
